def ref(inp):
    t = inp.split()
    X, Y, Z = int(t[0]), int(t[1]), int(t[2])

    # Exhaustive DP over sequences of pieces. State: how many of each piece
    # remain, and the last (up to) two characters of the string built so far.
    # Appending a piece is allowed iff the new string contains no "AAA" or "BBB".
    # Since the tail holds at most 2 chars and a piece has 2 chars, checking
    # tail+piece covers every substring that crosses the boundary.
    @lru_cache(maxsize=None)
    def f(i, j, k, tail):
        best = 0
        # use an "AA" piece
        if i < X:
            s = tail + "AA"
            if "AAA" not in s and "BBB" not in s:
                best = max(best, 2 + f(i + 1, j, k, s[-2:]))
        # use a "BB" piece
        if j < Y:
            s = tail + "BB"
            if "AAA" not in s and "BBB" not in s:
                best = max(best, 2 + f(i, j + 1, k, s[-2:]))
        # use an "AB" piece
        if k < Z:
            s = tail + "AB"
            if "AAA" not in s and "BBB" not in s:
                best = max(best, 2 + f(i, j, k + 1, s[-2:]))
        return best

    return str(f(0, 0, 0, ""))
