    # All positive palindromic integers strictly less than 10^9.
    res = []
    for L in range(1, 10):
        h = (L + 1) // 2
        for half in range(10 ** (h - 1), 10 ** h):
            s = str(half)
            if L % 2:
                full = s + s[-2::-1]
            else:
                full = s + s[::-1]
            v = int(full)
            if len(full) == L and 1 <= v < 10 ** 9:
                res.append(v)
    return sorted(set(res))


