    # tokens whose list is a palindrome (token i reversed equals token k+1-i as
    # strings, which makes S a string palindrome) and whose product is N.
    # Peel off outer pairs (t, rev t) with product p = t*rev(t) > 1 dividing M,
    # until the remaining value is 1 (empty inner list) or is itself a
    # zero-free palindromic token (single middle token).
    memo = {}

    def f(M):
        if M in memo:
            return memo[M]
        res = None
        if _zf(M) and str(M) == str(M)[::-1]:
            res = [str(M)]
        else:
            for t in _divisors(M):
                if t == 1 or not _zf(t):
                    continue
                r = _rev(t)
                if not _zf(r):
